-- Phone notifications (Web Push) for to-do reminders and prep reminders.
--
-- How it works: each phone that turns notifications on saves its push "address"
-- (push_subscriptions). Every minute, pg_cron asks the `push` Edge Function to send
-- whatever reminders are due (push_due_reminders), and each one is recorded in
-- reminders_sent so it goes out once. The push signing keys are generated by the
-- Edge Function on first use and kept in private.push_keys (server only).
-- The every-minute schedule is in 0008.

-- Reminder times are worked out in the family's time zone (set from the phone that
-- turns notifications on).
alter table public.families
  add column timezone text not null default 'America/Los_Angeles' check (length(timezone) between 1 and 64);

create table public.push_subscriptions (
  endpoint   text primary key check (length(endpoint) between 1 and 1000),
  user_id    uuid not null default auth.uid() references auth.users (id) on delete cascade,
  family_id  uuid not null references public.families (id) on delete cascade,
  p256dh     text not null check (length(p256dh) between 1 and 200),
  auth       text not null check (length(auth) between 1 and 100),
  created_at timestamptz not null default now()
);
create index on public.push_subscriptions (family_id);
create index on public.push_subscriptions (user_id);
alter table public.push_subscriptions enable row level security;
-- People can see their own devices; changes go through the functions below.
create policy "own devices" on public.push_subscriptions for select to authenticated
  using (user_id = (select auth.uid()));

create table public.reminders_sent (
  task_id        uuid not null references public.tasks (id) on delete cascade,
  minutes_before int  not null,
  sent_at        timestamptz not null default now(),
  primary key (task_id, minutes_before)
);
alter table public.reminders_sent enable row level security;   -- no policies: server only

create table private.push_keys (
  id          int primary key default 1 check (id = 1),
  public_key  text not null,
  private_key text not null,
  created_at  timestamptz not null default now()
);

-- If a to-do's day, time or reminders change (or it's unticked), its reminders can go out again.
create function private.reset_reminders() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (new.due_on, new.due_time, new.remind_before) is distinct from (old.due_on, old.due_time, old.remind_before)
     or (old.done_at is not null and new.done_at is null) then
    delete from public.reminders_sent where task_id = new.id;
  end if;
  return new;
end $$;
create trigger tasks_reset_reminders after update on public.tasks
  for each row execute function private.reset_reminders();

-- This device wants notifications. A browser has one address, so whoever used it
-- before is replaced. Also records the family's time zone.
create function public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_tz text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare fid uuid := private.my_family_id();
begin
  if fid is null then raise exception 'Join or create a family first'; end if;
  delete from public.push_subscriptions where endpoint = p_endpoint;
  insert into public.push_subscriptions (endpoint, user_id, family_id, p256dh, auth)
    values (p_endpoint, (select auth.uid()), fid, p_p256dh, p_auth);
  if p_tz is not null and exists (select 1 from pg_catalog.pg_timezone_names where name = p_tz) then
    update public.families set timezone = p_tz where id = fid;
  end if;
end $$;

create function public.remove_push_subscription(p_endpoint text)
returns void language sql security definer set search_path = '' as $$
  delete from public.push_subscriptions where endpoint = p_endpoint and user_id = (select auth.uid());
$$;

revoke all on function public.save_push_subscription(text, text, text, text) from public, anon;
revoke all on function public.remove_push_subscription(text) from public, anon;
grant execute on function public.save_push_subscription(text, text, text, text) to authenticated;
grant execute on function public.remove_push_subscription(text) to authenticated;

-- Server only (Edge Function, service role): reminders due in the last 30 minutes and
-- not yet sent. Prep reminders with a time always remind at the time.
create function public.push_due_reminders()
returns table (task_id uuid, minutes_before int, family_id uuid, title text, visibility text,
               owner_id uuid, due_on date, due_time time, is_prep boolean, timezone text)
language sql stable security definer set search_path = '' as $$
  with t as (
    select k.*, f.timezone as tz
    from public.tasks k join public.families f on f.id = k.family_id
    where k.done_at is null and k.due_on between current_date - 8 and current_date + 8
  ), o as (
    select t.*, m.m
    from t cross join lateral (
      select distinct x as m
      from unnest(t.remind_before || case when t.planned_meal_id is not null and t.due_time is not null
                                          then array[0] else array[]::int[] end) as x
    ) m
  )
  select o.id, o.m, o.family_id, o.title, o.visibility, o.owner_id, o.due_on, o.due_time,
         o.planned_meal_id is not null, o.tz
  from o
  where ((o.due_on + coalesce(o.due_time, time '09:00')) at time zone o.tz) - make_interval(mins => o.m)
          between now() - interval '30 minutes' and now()
    and not exists (select 1 from public.reminders_sent r where r.task_id = o.id and r.minutes_before = o.m)
$$;

create function public.push_keys() returns table (public_key text, private_key text)
language sql stable security definer set search_path = '' as $$
  select public_key, private_key from private.push_keys
$$;
create function public.push_keys_init(p_public text, p_private text) returns void
language sql security definer set search_path = '' as $$
  insert into private.push_keys (public_key, private_key) values (p_public, p_private) on conflict (id) do nothing
$$;
revoke all on function public.push_due_reminders() from public, anon, authenticated;
revoke all on function public.push_keys() from public, anon, authenticated;
revoke all on function public.push_keys_init(text, text) from public, anon, authenticated;
grant execute on function public.push_due_reminders() to service_role;
grant execute on function public.push_keys() to service_role;
grant execute on function public.push_keys_init(text, text) to service_role;
